:root {
  --bg: #05070b;
  --panel: rgba(10, 12, 16, 0.72);
  --panel-border: rgba(255, 255, 255, 0.1);
  --text: #edf4ff;
  --accent: #fca311;
  --danger: #ff5d5d;
  --success: #7ee7a3;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at center, #141c2c 0%, #090d15 58%, #020407 100%);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
}

body {
  position: relative;
}

canvas {
  display: block;
  width: 100vw;
  height: 100vh;
  background: #000;
  cursor: crosshair;
}

#ui {
  position: fixed;
  inset: 0;
  pointer-events: none;
}

#title, #subtitle, #message, #controls, #hud, #startButton {
  pointer-events: auto;
}

#title {
  position: absolute;
  top: 24px;
  left: 50%;
  transform: translateX(-50%);
  font-size: clamp(20px, 3vw, 42px);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 900;
  text-shadow: 0 0 24px rgba(255, 255, 255, 0.35);
}

#subtitle {
  position: absolute;
  top: 68px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 14px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  opacity: 0.8;
}

#startButton {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  padding: 16px 30px;
  border: 1px solid rgba(255, 255, 255, 0.25);
  background: rgba(25, 30, 42, 0.9);
  color: var(--text);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border-radius: 12px;
  cursor: pointer;
  box-shadow: 0 0 28px rgba(252, 163, 17, 0.22);
}

.panel {
  position: absolute;
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 12px;
  backdrop-filter: blur(6px);
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.25);
}

#hud {
  left: 18px;
  bottom: 18px;
  padding: 12px 16px;
  width: min(260px, calc(100vw - 36px));
}

.stat-row {
  display: grid;
  grid-template-columns: 52px 1fr 52px;
  align-items: center;
  gap: 10px;
  margin: 8px 0;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.stat-row.compact {
  grid-template-columns: 52px 44px 52px 1fr;
}

.meter {
  background: rgba(255,255,255,0.1);
  height: 10px;
  border-radius: 999px;
  overflow: hidden;
}

#powerFill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, var(--success), #c3ffc0, var(--accent));
  transition: width 0.15s linear;
}

#message {
  left: 50%;
  bottom: 110px;
  transform: translateX(-50%);
  padding: 10px 16px;
  font-size: 13px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  max-width: min(500px, calc(100vw - 30px));
  text-align: center;
}

#controls {
  right: 18px;
  bottom: 18px;
  padding: 10px 12px;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.9;
}

.small {
  font-size: 10px !important;
}

.hidden {
  display: none !important;
}

@media (max-width: 700px) {
  #title { top: 16px; letter-spacing: 0.08em; }
  #subtitle { top: 58px; letter-spacing: 0.12em; }
  #controls { display: none; }
  #message { bottom: 120px; }
}

const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);

const startButton = document.getElementById('startButton');
const hud = document.getElementById('hud');
const message = document.getElementById('message');
const powerFill = document.getElementById('powerFill');
const powerValue = document.getElementById('powerValue');
const nightValue = document.getElementById('nightValue');
const clockValue = document.getElementById('clockValue');

const state = {
  running: false,
  won: false,
  pointerLocked: false,
  power: 100,
  night: 1,
  time: 0,
  lastTime: 0,
  cameraYaw: 0,
  cameraPitch: 0,
  player: {
    x: 0,
    y: 1.7,
    z: 4.5,
    vx: 0,
    vz: 0,
    speed: 3,
    sprint: 5,
  },
  keys: Object.create(null),
  doors: { left: false, right: false },
  doorCooldown: 0,
  enemy: {
    active: false,
    x: -4,
    y: 1.6,
    z: -4,
    speed: 0.9,
    phase: 0,
    state: 'idle',
    jumpScareTimer: 0,
  },
};

const room = {
  width: 18,
  depth: 18,
  wall: 2.4,
  floorY: 0,
  doorLeftX: -5.5,
  doorRightX: 5.5,
  roomBound: 7.5,
};

const keys = {
  KeyW: 'forward',
  KeyS: 'backward',
  KeyA: 'left',
  KeyD: 'right',
  ShiftLeft: 'sprint',
  ShiftRight: 'sprint',
  KeyQ: 'doorLeft',
  KeyE: 'doorRight',
  KeyR: 'restart',
};

function resize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  canvas.width = Math.max(1, w * window.devicePixelRatio);
  canvas.height = Math.max(1, h * window.devicePixelRatio);
  ctx.setTransform(window.devicePixelRatio, 0, 0, window.devicePixelRatio, 0, 0);
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function formatClock(t) {
  const totalMinutes = Math.floor(t / 60);
  const hour = (Math.floor(totalMinutes / 60) % 12) || 12;
  const minute = Math.floor(totalMinutes % 60);
  const suffix = totalMinutes >= 12 * 60 ? 'AM' : 'PM';
  return `${hour}:${String(minute).padStart(2, '0')} ${suffix}`;
}

function updateHUD() {
  powerFill.style.width = `${state.power}%`;
  powerValue.textContent = `${Math.round(state.power)}%`;
  nightValue.textContent = `${state.night}`;
  clockValue.textContent = formatClock(state.time);
}

function setMessage(text) {
  message.textContent = text;
}

function setPointerLock(lock) {
  state.pointerLocked = lock;
  if (lock) {
    canvas.requestPointerLock();
  } else {
    document.exitPointerLock();
  }
}

function startGame() {
  state.running = true;
  state.won = false;
  state.power = 100;
  state.time = 0;
  state.player.x = 0;
  state.player.z = 4.5;
  state.player.y = 1.7;
  state.cameraYaw = 0;
  state.cameraPitch = 0;
  state.enemy.x = -4;
  state.enemy.z = -4;
  state.enemy.active = false;
  state.enemy.phase = 0;
  state.enemy.state = 'idle';
  startButton.classList.add('hidden');
  setMessage('Night 1: Stay alive until 6 AM');
  updateHUD();
}

function toggleDoor(side) {
  if (!state.running) return;
  if (state.doorCooldown > 0) return;
  const active = state.doors[side];
  if (active) {
    state.doors[side] = false;
  } else if (state.power > 5) {
    state.doors[side] = true;
  }
  state.doorCooldown = 0.2;
}

function setKey(key, isDown) {
  const mapping = keys[key];
  if (!mapping) return;
  state.keys[mapping] = isDown;
  if (mapping === 'doorLeft' && isDown) toggleDoor('left');
  if (mapping === 'doorRight' && isDown) toggleDoor('right');
  if (mapping === 'restart' && isDown) resetToMenu();
}

function resetToMenu() {
  state.running = false;
  state.won = false;
  state.doors.left = false;
  state.doors.right = false;
  state.power = 100;
  startButton.classList.remove('hidden');
  setMessage('Click to lock the pointer and begin.');
  updateHUD();
}

function updatePlayer(dt) {
  const moveX = (state.keys.forward ? 1 : 0) - (state.keys.backward ? 1 : 0);
  const moveZ = (state.keys.right ? 1 : 0) - (state.keys.left ? 1 : 0);
  const isSprinting = state.keys.sprint && state.power > 0;

  let speed = isSprinting ? state.player.sprint : state.player.speed;
  const forwardX = Math.sin(state.cameraYaw);
  const forwardZ = Math.cos(state.cameraYaw);
  const strafeX = Math.cos(state.cameraYaw);
  const strafeZ = -Math.sin(state.cameraYaw);

  let dx = forwardX * moveX + strafeX * moveZ;
  let dz = forwardZ * moveX + strafeZ * moveZ;

  const len = Math.hypot(dx, dz) || 1;
  dx /= len;
  dz /= len;

  state.player.x += dx * speed * dt;
  state.player.z += dz * speed * dt;

  state.player.x = clamp(state.player.x, -room.roomBound, room.roomBound);
  state.player.z = clamp(state.player.z, -room.roomBound, room.roomBound);

  if (isSprinting) {
    state.power = clamp(state.power - 15 * dt, 0, 100);
  } else {
    state.power = clamp(state.power + 6 * dt, 0, 100);
  }

  if (state.doors.left || state.doors.right) {
    state.power = clamp(state.power - 7 * dt, 0, 100);
  }
}

function updateEnemy(dt) {
  if (!state.running) return;

  const doorBlock = state.doors.left || state.doors.right;
  if (!state.enemy.active) {
    state.enemy.phase += dt;
    if (state.enemy.phase > 15) {
      state.enemy.active = true;
      state.enemy.state = 'stalking';
      setMessage('The animatronic is moving.');
    }
  }

  if (!state.enemy.active) return;

  const targetX = state.player.x;
  const targetZ = state.player.z;
  const dx = targetX - state.enemy.x;
  const dz = targetZ - state.enemy.z;
  const dist = Math.hypot(dx, dz);

  if (dist < 2.4) {
    if (state.enemy.state !== 'attack') {
      state.enemy.state = 'attack';
      state.enemy.jumpScareTimer = 1.4;
      setMessage('Jumpscare!');
    }
  } else {
    state.enemy.state = 'stalking';
  }

  if (state.enemy.jumpScareTimer > 0) {
    state.enemy.jumpScareTimer -= dt;
    if (state.enemy.jumpScareTimer <= 0) {
      resetToMenu();
      setMessage('You were caught by the animatronic.');
      return;
    }
  }

  const moveCoeff = doorBlock ? 0.6 : 1;
  const desiredSpeed = state.enemy.speed * moveCoeff * (1 + state.night * 0.15);
  if (dist > 0.1) {
    state.enemy.x += (dx / dist) * desiredSpeed * dt;
    state.enemy.z += (dz / dist) * desiredSpeed * dt;
  }

  if (doorBlock && dist < 6) {
    state.enemy.x += Math.sin(state.time * 0.7) * 0.01;
  }
}

function updateClock(dt) {
  if (!state.running) return;
  state.time += dt;
  if (state.time >= 6 * 60) {
    state.running = false;
    state.won = true;
    setMessage('6 AM reached. You survived the night.');
    startButton.textContent = 'Play Again';
    startButton.classList.remove('hidden');
    return;
  }

  const minutes = state.time / 60;
  if (minutes > 1 && minutes < 2.5) {
    state.night = 1;
  } else if (minutes > 2.5 && minutes < 4) {
    state.night = 2;
  } else if (minutes > 4) {
    state.night = 3;
  }

  if (state.power <= 0) {
    setMessage('Power depleted. The building is too dark.');
    resetToMenu();
  }
}

function drawFloor() {
  const w = canvas.width / window.devicePixelRatio;
  const h = canvas.height / window.devicePixelRatio;

  ctx.fillStyle = '#0a0d12';
  ctx.fillRect(0, 0, w, h);

  const centerX = w / 2;
  const centerY = h / 2;
  const floorHalf = 220;

  ctx.save();
  ctx.translate(centerX, centerY);
  ctx.fillStyle = '#2a313d';
  ctx.fillRect(-floorHalf, -floorHalf, floorHalf * 2, floorHalf * 2);

  for (let i = -9; i <= 9; i++) {
    ctx.strokeStyle = i === 0 ? 'rgba(255,255,255,0.18)' : 'rgba(255,255,255,0.08)';
    ctx.beginPath();
    ctx.moveTo(-floorHalf, i * 22);
    ctx.lineTo(floorHalf, i * 22);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(i * 22, -floorHalf);
    ctx.lineTo(i * 22, floorHalf);
    ctx.stroke();
  }

  ctx.restore();
}

function drawRoom() {
  const cx = canvas.width / window.devicePixelRatio / 2;
  const cy = canvas.height / window.devicePixelRatio / 2;
  ctx.save();
  ctx.translate(cx, cy);

  const wall = 360;
  const half = wall * 0.5;
  ctx.fillStyle = 'rgba(90, 96, 108, 0.8)';
  ctx.fillRect(-half, -half, wall, wall);

  ctx.strokeStyle = 'rgba(180, 190, 205, 0.7)';
  ctx.strokeRect(-half, -half, wall, wall);

  ctx.fillStyle = '#1a1d22';
  ctx.fillRect(-wall * 0.2, -half, wall * 0.4, wall * 0.18);
  ctx.fillRect(-wall * 0.2, half - wall * 0.18, wall * 0.4, wall * 0.18);

  const doorW = wall * 0.12;
  const doorH = wall * 0.22;
  const leftDoorX = -wall * 0.44;
  const rightDoorX = wall * 0.44;

  ctx.fillStyle = state.doors.left ? '#d9873a' : '#4a4a4a';
  ctx.fillRect(leftDoorX, -doorH / 2, doorW, doorH);
  ctx.fillStyle = state.doors.right ? '#d9873a' : '#4a4a4a';
  ctx.fillRect(rightDoorX, -doorH / 2, doorW, doorH);

  ctx.restore();
}

function drawPlayer() {
  const x = canvas.width / window.devicePixelRatio / 2 + (state.player.x / room.roomBound) * 220;
  const z = canvas.height / window.devicePixelRatio / 2 + (state.player.z / room.roomBound) * 220;

  ctx.save();
  ctx.translate(x, z);
  ctx.fillStyle = '#7dd3fc';
  ctx.beginPath();
  ctx.arc(0, 0, 12, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#f1f5f9';
  ctx.fillRect(-4, 8, 8, 18);
  ctx.restore();
}

function drawEnemy() {
  const x = canvas.width / window.devicePixelRatio / 2 + (state.enemy.x / room.roomBound) * 220;
  const z = canvas.height / window.devicePixelRatio / 2 + (state.enemy.z / room.roomBound) * 220;

  ctx.save();
  ctx.translate(x, z);
  ctx.fillStyle = state.enemy.state === 'attack' ? '#ff5d5d' : '#d946ef';
  ctx.beginPath();
  ctx.arc(0, 0, 14, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#111827';
  ctx.fillRect(-2, 12, 4, 18);
  ctx.restore();
}

function drawScene() {
  drawFloor();
  drawRoom();
  drawPlayer();
  if (state.enemy.active) drawEnemy();
}

function gameLoop(timestamp) {
  const dt = Math.min((timestamp - state.lastTime) / 1000 || 0.016, 0.03);
  state.lastTime = timestamp;

  if (state.running) {
    updatePlayer(dt);
    updateEnemy(dt);
    updateClock(dt);
    if (state.doorCooldown > 0) state.doorCooldown -= dt;
  }

  drawScene();
  updateHUD();
  requestAnimationFrame(gameLoop);
}

window.addEventListener('resize', resize);
window.addEventListener('keydown', (event) => {
  if (event.code === 'KeyQ' || event.code === 'KeyE' || event.code === 'KeyR') {
    event.preventDefault();
  }
  if (event.code === 'Escape') {
    setPointerLock(false);
    return;
  }
  setKey(event.code, true);
});

window.addEventListener('keyup', (event) => setKey(event.code, false));
window.addEventListener('pointerlockchange', () => {
  state.pointerLocked = document.pointerLockElement === canvas;
  if (!state.pointerLocked && state.running) {
    setMessage('Pointer unlocked. Press start to continue.');
  }
});

window.addEventListener('mousemove', (event) => {
  if (!state.pointerLocked || !state.running) return;
  state.cameraYaw -= event.movementX * 0.0025;
  state.cameraPitch = clamp(state.cameraPitch - event.movementY * 0.0018, -1.2, 1.2);
});

canvas.addEventListener('click', () => {
  if (!state.running) {
    startGame();
    setPointerLock(true);
  } else if (!state.pointerLocked) {
    setPointerLock(true);
  }
});

startButton.addEventListener('click', () => {
  startGame();
  setPointerLock(true);
});

resize();
updateHUD();
setMessage('Click the start button or the screen to begin.');
requestAnimationFrame(gameLoop);

